'use strict';
let friendTab='friends', liked=false;

function renderFriends(){
 const friends=[{name:'박서준',status:'오늘도 좋은 하루',music:'좋은 날 · 아이유'},{name:'미나',status:'한국어 같이 배워요',music:''},{name:'제이',status:'새로운 이야기를 만드는 중',music:''}].filter(f=>matchText(f.name+' '+f.status));
 const rows=friends.map((f,i)=>`<button class="list-row" data-action="friend-profile" data-id="${f.name}"><img class="avatar" src="assets/kakao/profile-${i+1}.png" alt=""><span class="row-copy"><strong>${f.name}</strong><p>${f.status}</p></span>${f.music?`<span class="friend-music">${f.music} ▷</span>`:''}</button>`).join('');
 return `<div class="friend-feed"><div class="friend-tabs"><button class="${friendTab==='friends'?'selected':''}" data-action="friend-tab" data-id="friends" aria-pressed="${friendTab==='friends'}">친구</button><button class="${friendTab==='news'?'selected':''}" data-action="friend-tab" data-id="news" aria-pressed="${friendTab==='news'}">소식</button></div>${friendTab==='friends'?`<button class="classic-profile" data-action="passport"><img src="assets/kakao/profile-1.png" alt=""><span><strong>김하늘</strong><p>나의 취향, 하나의 카카오</p></span><span class="profile-edit">내 활동</span></button><section class="classic-section">${sectionTitle('Playground')}<button class="list-row" data-view="one"><span class="classic-channel-icon">${icon('one')}</span><span class="row-copy"><strong>Playground</strong><p>창작마당과 한국어 학습</p></span><span class="row-side">${icon('arrow')}</span></button></section><section class="classic-section">${sectionTitle('친구',friends.length)}${rows||'<p class="friend-empty">검색 결과가 없습니다.</p>'}</section><button class="news-banner" data-view="one"><div><strong>톡에서 시작하는 나만의 즐거움</strong><span>만들고, 배우고, 함께 이야기해요</span></div><img src="assets/kakao/apeach-profile.png" alt="어피치"></button>`:`<button class="news-banner" data-view="one"><div><strong>톡에서 만나는 새로운 즐거움</strong><span>Playground, 지금 만나보세요</span></div><img src="assets/kiwi/party.png" alt=""></button><article class="friend-post"><div class="post-author"><img src="assets/kakao/profile-1.png" alt=""><div><strong>박서준</strong><p>2일 전 · 프로필 업데이트</p></div><button class="icon-button" data-action="post-menu" aria-label="게시물 메뉴">${icon('more')}</button></div><img class="post-photo" src="assets/kiwi/cafe.png" alt="햇살이 들어오는 카페의 창가와 테이블"><div class="post-reactions"><button data-action="like-post" aria-label="좋아요" aria-pressed="${liked}">${icon('heart')} ${liked?4:3}</button><button data-action="post-comment" aria-label="댓글">${icon('rooms')}</button></div></article>`}</div>`;
}
